import pandas as pd
import os

def analyze_hybrid_r1_r3():
    csv_path = 'output/trades_dynamic_threshold_CLEAN_REFERENCE_20260812.csv'
    
    if not os.path.exists(csv_path):
        print(f"❌ Error: Could not find {csv_path}")
        print("Make sure you have extracted the data files!")
        return

    clean = pd.read_csv(csv_path)
    clean['date'] = pd.to_datetime(clean['date'])

    # Count total daily trades generated by the original model
    day_counts = clean.groupby('date').size().reset_index(name='daily_count')
    clean = clean.merge(day_counts, on='date')
    clean['rank'] = clean.groupby('date').cumcount() + 1
    clean['year'] = clean['date'].dt.year

    # Apply exact logic:
    # If daily_count >= 3 -> keep rank 1 and rank 3
    # If daily_count < 3 -> keep rank 1 only
    mask_r1r3 = (clean['daily_count'] >= 3) & (clean['rank'].isin([1, 3]))
    mask_r1only = (clean['daily_count'] < 3) & (clean['rank'] == 1)

    final_trades = clean[mask_r1r3 | mask_r1only]

    yearly = final_trades.groupby('year').agg(
        Trades=('actual_pnl', 'count'),
        WinPct=('actual_pnl', lambda x: round((x>0).mean()*100,1)),
        AvgPnL=('actual_pnl', 'mean')
    ).reset_index()

    print('\n' + '='*50)
    print(' 🏆 SNIPER ALGORITHM (R1+R3 HYBRID) BACKTEST ')
    print('='*50)
    for idx, row in yearly.iterrows():
        print(f'{int(row["year"])}: {int(row["Trades"]):>4} trades | {row["WinPct"]:>5.1f}% Win | Avg Rs {row["AvgPnL"]:>6,.0f}')
    
    print('-'*50)
    overall_win = (final_trades["actual_pnl"]>0).mean()*100
    overall_avg = final_trades["actual_pnl"].mean()
    print(f'OVERALL: {len(final_trades)} trades | {overall_win:.1f}% Win | Avg Rs {overall_avg:,.0f}')
    print('='*50 + '\n')

if __name__ == '__main__':
    analyze_hybrid_r1_r3()
